-- A1 Beginner Listening
INSERT INTO lessons (id, title, description, language, category, order_index, estimated_minutes, content_json, unlocks_word_ids, unlocks_grammar_concepts)
VALUES (
  'spanish_a1_listening',
  'A1 Beginner Listening',
  'Practice listening comprehension with basic Spanish phrases and everyday conversations',
  'spanish',
  'listening',
  0,
  25,
  '{"sections":[{"type":"text","id":"intro","title":"Welcome to Listening Practice","content":"In this lesson, you will practice listening to basic Spanish phrases. Listen carefully to each phrase and try to understand the meaning. This will help you improve your comprehension skills.\n\nWe''ll cover:\n• Greetings and introductions\n• Numbers and age\n• Location and family\n• Likes and preferences\n• Time expressions","examples":["Focus on key words you recognize","Listen for numbers, greetings, and common words","Don''t worry if you don''t understand everything","Practice repeating phrases out loud"]},{"type":"text","id":"greetings_intro","title":"Greetings in Spanish","content":"Spanish has different greetings for different times of day. Learning these will help you start conversations naturally.","examples":["Buenos días - Good morning (until noon)","Buenas tardes - Good afternoon (noon to evening)","Buenas noches - Good evening/night","Hola - Hello (any time)"]},{"type":"example","id":"listening1","spanish_example":"Hola, ¿cómo estás?","english_translation":"Hello, how are you?","explanation":"A common greeting. \"Hola\" means hello, and \"¿cómo estás?\" means \"how are you?\" This is informal - use with friends and people your age."},{"type":"example","id":"listening1b","spanish_example":"Buenos días, ¿cómo está usted?","english_translation":"Good morning, how are you? (formal)","explanation":"This is the formal version. \"Usted\" is used to show respect to older people, teachers, or in professional settings."},{"type":"exercise","id":"exercise1","question":"Listen: \"Buenos días, me llamo María.\" What does this mean?","options":[{"text":"Good morning, my name is María","is_correct":true},{"text":"Good night, I am María","is_correct":false},{"text":"Hello, I like María","is_correct":false},{"text":"Goodbye, María","is_correct":false}],"explanation":"Correct! \"Buenos días\" means \"good morning\" and \"me llamo\" means \"my name is\"."},{"type":"exercise","id":"exercise1b","question":"Which greeting would you use at 2:00 PM?","options":[{"text":"Buenas tardes","is_correct":true},{"text":"Buenos días","is_correct":false},{"text":"Buenas noches","is_correct":false},{"text":"Buenos días","is_correct":false}],"explanation":"Correct! \"Buenas tardes\" is used in the afternoon (from noon until evening)."},{"type":"text","id":"numbers_intro","title":"Numbers and Age","content":"In Spanish, to say your age, you use \"tener\" (to have) instead of \"ser\" (to be). You literally say \"I have X years\".","examples":["Tengo veinte años - I am twenty years old","Tengo treinta años - I am thirty years old","¿Cuántos años tienes? - How old are you?"]},{"type":"example","id":"listening2","spanish_example":"Tengo veinte años","english_translation":"I am twenty years old","explanation":"\"Tengo\" means \"I have\" and \"años\" means \"years\". In Spanish, you say \"I have X years\" instead of \"I am X years old\"."},{"type":"example","id":"listening2b","spanish_example":"Mi hermana tiene quince años","english_translation":"My sister is fifteen years old","explanation":"Notice how \"tiene\" (has) is used for \"she\". The verb changes: yo tengo, tú tienes, él/ella tiene."},{"type":"exercise","id":"exercise2","question":"Listen: \"¿Cuántos años tienes?\" What is the person asking?","options":[{"text":"How old are you?","is_correct":true},{"text":"What is your name?","is_correct":false},{"text":"Where are you from?","is_correct":false},{"text":"How are you?","is_correct":false}],"explanation":"Correct! \"¿Cuántos años tienes?\" means \"How old are you?\""},{"type":"exercise","id":"exercise2b","question":"How would you say \"I am twenty-five years old\" in Spanish?","options":[{"text":"Tengo veinticinco años","is_correct":true},{"text":"Soy veinticinco años","is_correct":false},{"text":"Tengo veinte y cinco años","is_correct":false},{"text":"Estoy veinticinco años","is_correct":false}],"explanation":"Correct! Use \"tengo\" (I have) with \"años\" (years). Veinticinco is written as one word."},{"type":"text","id":"location_intro","title":"Talking About Location","content":"To say where you are from or where you live, Spanish uses different verbs:\n• \"Ser de\" = to be from (origin)\n• \"Vivir en\" = to live in (current residence)","examples":["Soy de España - I am from Spain","Vivo en Madrid - I live in Madrid","Soy de México pero vivo en Estados Unidos - I am from Mexico but I live in the United States"]},{"type":"example","id":"listening3","spanish_example":"Soy de España","english_translation":"I am from Spain","explanation":"\"Soy de\" means \"I am from\". This tells where you were born or your nationality."},{"type":"example","id":"listening3b","spanish_example":"Vivo en Madrid con mi familia","english_translation":"I live in Madrid with my family","explanation":"\"Vivo en\" means \"I live in\" (current residence). \"Con mi familia\" means \"with my family\"."},{"type":"exercise","id":"exercise3","question":"Listen: \"Vivo en Madrid con mi familia.\" What does this mean?","options":[{"text":"I live in Madrid with my family","is_correct":true},{"text":"I visit Madrid with friends","is_correct":false},{"text":"I work in Madrid","is_correct":false},{"text":"I like Madrid","is_correct":false}],"explanation":"Correct! \"Vivo en\" means \"I live in\" and \"con mi familia\" means \"with my family\"."},{"type":"exercise","id":"exercise3b","question":"What is the difference between \"Soy de\" and \"Vivo en\"?","options":[{"text":"\"Soy de\" = origin, \"Vivo en\" = current residence","is_correct":true},{"text":"They mean the same thing","is_correct":false},{"text":"\"Soy de\" = current residence, \"Vivo en\" = origin","is_correct":false},{"text":"Both mean \"I am from\"","is_correct":false}],"explanation":"Correct! \"Soy de\" tells where you are from (origin/nationality), while \"Vivo en\" tells where you currently live."},{"type":"text","id":"likes_intro","title":"Expressing Likes: Me Gusta","content":"In Spanish, you don''t say \"I like coffee\". Instead, you say \"coffee is pleasing to me\" using \"me gusta\".\n\n• Me gusta = I like (singular)\n• Me gustan = I like (plural)\n• ¿Qué te gusta? = What do you like?","examples":["Me gusta el café - I like coffee","Me gustan los libros - I like books","No me gusta el té - I don''t like tea"]},{"type":"example","id":"listening4","spanish_example":"Me gusta el café","english_translation":"I like coffee","explanation":"\"Me gusta\" means \"I like\". In Spanish, you say \"coffee is pleasing to me\" rather than \"I like coffee\"."},{"type":"example","id":"listening4b","spanish_example":"Me gustan los libros y la música","english_translation":"I like books and music","explanation":"Notice \"me gustan\" (plural) is used because \"libros\" (books) is plural. Use \"gusta\" for singular, \"gustan\" for plural."},{"type":"exercise","id":"exercise4","question":"Listen: \"¿Qué te gusta hacer?\" What is the person asking?","options":[{"text":"What do you like to do?","is_correct":true},{"text":"What is your name?","is_correct":false},{"text":"Where do you live?","is_correct":false},{"text":"How are you?","is_correct":false}],"explanation":"Correct! \"¿Qué te gusta hacer?\" means \"What do you like to do?\""},{"type":"exercise","id":"exercise4b","question":"Which is correct: \"Me gusta los libros\" or \"Me gustan los libros\"?","options":[{"text":"Me gustan los libros","is_correct":true},{"text":"Me gusta los libros","is_correct":false},{"text":"Both are correct","is_correct":false},{"text":"Me gusta el libros","is_correct":false}],"explanation":"Correct! Use \"gustan\" (plural) because \"libros\" (books) is plural. The verb must agree with what you like."},{"type":"text","id":"time_intro","title":"Telling Time","content":"To tell time in Spanish:\n• \"Son las\" + number (for most hours)\n• \"Es la\" + number (for 1:00)\n• \"de la mañana\" = in the morning\n• \"de la tarde\" = in the afternoon\n• \"de la noche\" = in the evening/night","examples":["Son las tres de la tarde - It is 3:00 PM","Es la una de la mañana - It is 1:00 AM","Son las diez de la noche - It is 10:00 PM"]},{"type":"example","id":"listening5","spanish_example":"Son las tres de la tarde","english_translation":"It is three in the afternoon","explanation":"\"Son las\" is used for telling time (except 1:00). \"De la tarde\" means \"in the afternoon\" (from noon to evening)."},{"type":"example","id":"listening5b","spanish_example":"Es la una de la mañana","english_translation":"It is one in the morning","explanation":"For 1:00, use \"Es la\" (singular) instead of \"Son las\" (plural). \"De la mañana\" means \"in the morning\"."},{"type":"exercise","id":"exercise5","question":"Listen: \"Son las tres de la tarde.\" What time is it?","options":[{"text":"3:00 PM (three in the afternoon)","is_correct":true},{"text":"3:00 AM (three in the morning)","is_correct":false},{"text":"13:00 (one o''clock)","is_correct":false},{"text":"30:00 (thirty o''clock)","is_correct":false}],"explanation":"Correct! \"Son las tres de la tarde\" means \"It is three in the afternoon\" (3:00 PM)."},{"type":"exercise","id":"exercise5b","question":"How would you say \"It is 1:00 PM\" in Spanish?","options":[{"text":"Es la una de la tarde","is_correct":true},{"text":"Son las una de la tarde","is_correct":false},{"text":"Es la uno de la tarde","is_correct":false},{"text":"Son las uno de la tarde","is_correct":false}],"explanation":"Correct! For 1:00, use \"Es la una\" (singular). \"Una\" is the feminine form of \"one\" used for time."},{"type":"text","id":"feelings_intro","title":"Expressing Feelings with Tener","content":"In Spanish, many feelings and states use \"tener\" (to have) instead of \"estar\" (to be):\n• Tengo hambre - I am hungry\n• Tengo sed - I am thirsty\n• Tengo frío - I am cold\n• Tengo calor - I am hot","examples":["Tengo hambre - I am hungry (literally: I have hunger)","Tengo sed - I am thirsty (literally: I have thirst)","Tengo sueño - I am sleepy (literally: I have sleepiness)"]},{"type":"example","id":"listening6","spanish_example":"Tengo hambre","english_translation":"I am hungry","explanation":"Literally means \"I have hunger\". In Spanish, you express feelings and states using \"tener\" (to have)."},{"type":"exercise","id":"exercise6","question":"How would you say \"I am thirsty\" in Spanish?","options":[{"text":"Tengo sed","is_correct":true},{"text":"Estoy sed","is_correct":false},{"text":"Soy sed","is_correct":false},{"text":"Tengo hambre","is_correct":false}],"explanation":"Correct! \"Tengo sed\" means \"I am thirsty\". Use \"tener\" (to have) for feelings like hunger and thirst."},{"type":"text","id":"tips","title":"Listening Tips","content":"Great job completing this lesson! Here are some tips to continue improving your listening skills:\n\n1. Listen to Spanish audio regularly, even if you don''t understand everything\n2. Start with slow, clear speech\n3. Focus on understanding the main idea first\n4. Practice with familiar topics\n5. Repeat phrases out loud to improve pronunciation\n6. Watch Spanish videos with subtitles\n7. Listen to Spanish music and try to catch words\n8. Practice with language learning apps daily","examples":["Watch Spanish videos with subtitles","Listen to Spanish music and try to catch words","Practice with language learning apps","Have conversations with native speakers"]}]}'::jsonb,
  ARRAY['hola', 'buenos_días', 'buenas_tardes', 'buenas_noches', 'cómo', 'estás', 'está', 'llamo', 'años', 'vivo', 'familia', 'gusta', 'gustan', 'café', 'hambre', 'sed', 'tarde', 'mañana', 'noche']::TEXT[],
  ARRAY['greetings', 'introductions', 'basic_questions', 'tener_expressions', 'time_expressions']::TEXT[]
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  estimated_minutes = EXCLUDED.estimated_minutes,
  content_json = EXCLUDED.content_json,
  unlocks_word_ids = EXCLUDED.unlocks_word_ids,
  unlocks_grammar_concepts = EXCLUDED.unlocks_grammar_concepts,
  updated_at = NOW();

-- Present Tense Verbs
INSERT INTO lessons (id, title, description, language, category, order_index, estimated_minutes, content_json, unlocks_word_ids, unlocks_grammar_concepts)
VALUES (
  'spanish_present_tense_verbs',
  'Present Tense Verbs',
  'Learn how to conjugate and use Spanish present tense verbs',
  'spanish',
  'verb_tenses',
  1,
  30,
  '{"sections":[{"type":"text","id":"intro","title":"Introduction to Present Tense","content":"The present tense in Spanish is used to describe:\n• Actions happening right now\n• Habitual actions (things you do regularly)\n• General truths\n\nSpanish verbs change their endings based on the subject (who is doing the action).","examples":["Yo hablo español (I speak Spanish) - happening now","Tú comes manzanas todos los días (You eat apples every day) - habitual","El sol sale por el este (The sun rises in the east) - general truth"]},{"type":"text","id":"ar_verbs_intro","title":"-AR Verbs: The Most Common Type","content":"Most Spanish verbs end in -AR. To conjugate them, remove the -AR ending and add the appropriate ending for each subject:\n\n• Yo: -o\n• Tú: -as\n• Él/Ella/Usted: -a\n• Nosotros: -amos\n• Vosotros: -áis\n• Ellos/Ellas/Ustedes: -an","examples":["hablar (to speak): hablo, hablas, habla, hablamos, habláis, hablan","caminar (to walk): camino, caminas, camina, caminamos, camináis, caminan"]},{"type":"example","id":"example1","spanish_example":"Yo hablo español todos los días","english_translation":"I speak Spanish every day","explanation":"The verb \"hablar\" (to speak) ends in -o for \"yo\" (I). Notice how \"todos los días\" (every day) shows this is a habitual action."},{"type":"example","id":"example1b","spanish_example":"Tú hablas muy bien","english_translation":"You speak very well","explanation":"For \"tú\" (you informal), the ending is -as. \"Muy bien\" means \"very well\"."},{"type":"example","id":"example1c","spanish_example":"Él habla con su amigo","english_translation":"He speaks with his friend","explanation":"For \"él\" (he), the ending is -a. \"Con su amigo\" means \"with his friend\"."},{"type":"exercise","id":"exercise1","question":"How do you say \"I speak\" in Spanish?","options":[{"text":"Yo hablo","is_correct":true},{"text":"Yo hablas","is_correct":false},{"text":"Yo habla","is_correct":false},{"text":"Yo hablan","is_correct":false}],"explanation":"Correct! \"Yo hablo\" means \"I speak\". The verb \"hablar\" uses -o ending for \"yo\"."},{"type":"exercise","id":"exercise1b","question":"Which is the correct form of \"hablar\" (to speak) for \"tú\" (you)?","options":[{"text":"hablas","is_correct":true},{"text":"hablo","is_correct":false},{"text":"habla","is_correct":false},{"text":"hablan","is_correct":false}],"explanation":"Correct! \"Tú hablas\" means \"You speak\". The -as ending is used for \"tú\"."},{"type":"exercise","id":"exercise1c","question":"Complete: \"Nosotros _____ español.\" (We speak Spanish)","options":[{"text":"hablamos","is_correct":true},{"text":"hablan","is_correct":false},{"text":"habla","is_correct":false},{"text":"hablas","is_correct":false}],"explanation":"Correct! \"Nosotros hablamos\" means \"We speak\". The -amos ending is used for \"nosotros\"."},{"type":"text","id":"er_verbs_intro","title":"-ER Verbs: Second Type","content":"Many Spanish verbs end in -ER. The conjugation pattern is:\n\n• Yo: -o\n• Tú: -es\n• Él/Ella/Usted: -e\n• Nosotros: -emos\n• Vosotros: -éis\n• Ellos/Ellas/Ustedes: -en","examples":["comer (to eat): como, comes, come, comemos, coméis, comen","beber (to drink): bebo, bebes, bebe, bebemos, bebéis, beben"]},{"type":"example","id":"example2","spanish_example":"Yo como manzanas","english_translation":"I eat apples","explanation":"The verb \"comer\" (to eat) uses -o ending for \"yo\". Notice \"manzanas\" (apples) is plural."},{"type":"example","id":"example2b","spanish_example":"Ella come pan en el desayuno","english_translation":"She eats bread for breakfast","explanation":"For \"ella\" (she), the ending is -e. \"En el desayuno\" means \"for breakfast\"."},{"type":"exercise","id":"exercise2","question":"How do you say \"I eat\" in Spanish?","options":[{"text":"Yo como","is_correct":true},{"text":"Yo come","is_correct":false},{"text":"Yo comen","is_correct":false},{"text":"Yo comes","is_correct":false}],"explanation":"Correct! \"Yo como\" means \"I eat\". The verb \"comer\" (to eat) uses -o ending for \"yo\"."},{"type":"exercise","id":"exercise2b","question":"Complete: \"Tú _____ agua.\" (You drink water)","options":[{"text":"bebes","is_correct":true},{"text":"bebe","is_correct":false},{"text":"bebo","is_correct":false},{"text":"beben","is_correct":false}],"explanation":"Correct! \"Tú bebes\" means \"You drink\". The -es ending is used for \"tú\" with -ER verbs."},{"type":"text","id":"ir_verbs_intro","title":"-IR Verbs: Third Type","content":"Some Spanish verbs end in -IR. The conjugation is similar to -ER verbs:\n\n• Yo: -o\n• Tú: -es\n• Él/Ella/Usted: -e\n• Nosotros: -imos (different from -ER!)\n• Vosotros: -ís\n• Ellos/Ellas/Ustedes: -en","examples":["vivir (to live): vivo, vives, vive, vivimos, vivís, viven","escribir (to write): escribo, escribes, escribe, escribimos, escribís, escriben"]},{"type":"example","id":"example3","spanish_example":"Yo vivo en España","english_translation":"I live in Spain","explanation":"The verb \"vivir\" (to live) uses -o ending for \"yo\". Notice it''s similar to -ER verbs for most forms."},{"type":"example","id":"example3b","spanish_example":"Nosotros vivimos en Madrid","english_translation":"We live in Madrid","explanation":"For \"nosotros\" with -IR verbs, use -imos (not -emos like -ER verbs). This is the key difference!"},{"type":"exercise","id":"exercise3","question":"How do you say \"I write\" in Spanish?","options":[{"text":"Yo escribo","is_correct":true},{"text":"Yo escribes","is_correct":false},{"text":"Yo escribe","is_correct":false},{"text":"Yo escriben","is_correct":false}],"explanation":"Correct! \"Yo escribo\" means \"I write\". The verb \"escribir\" uses -o ending for \"yo\"."},{"type":"exercise","id":"exercise3b","question":"What is the difference between -ER and -IR verbs for \"nosotros\"?","options":[{"text":"-ER uses -emos, -IR uses -imos","is_correct":true},{"text":"They are the same","is_correct":false},{"text":"-ER uses -imos, -IR uses -emos","is_correct":false},{"text":"Both use -amos","is_correct":false}],"explanation":"Correct! -ER verbs use -emos for \"nosotros\", while -IR verbs use -imos. This is the main difference!"},{"type":"text","id":"practice_intro","title":"Practice: Mixing Verb Types","content":"Now let''s practice identifying and conjugating different verb types. Remember:\n• -AR verbs: hablo, hablas, habla, hablamos, habláis, hablan\n• -ER verbs: como, comes, come, comemos, coméis, comen\n• -IR verbs: vivo, vives, vive, vivimos, vivís, viven","examples":["Look at the infinitive ending to identify the type","Remove the ending and add the correct subject ending","Practice with common verbs you know"]},{"type":"exercise","id":"exercise4","question":"Which verb type is \"trabajar\" (to work)?","options":[{"text":"-AR verb","is_correct":true},{"text":"-ER verb","is_correct":false},{"text":"-IR verb","is_correct":false},{"text":"Irregular verb","is_correct":false}],"explanation":"Correct! \"Trabajar\" ends in -AR, so it''s an -AR verb. It conjugates: trabajo, trabajas, trabaja, trabajamos, trabajáis, trabajan."},{"type":"exercise","id":"exercise4b","question":"Complete: \"Él _____ en una oficina.\" (He works in an office)","options":[{"text":"trabaja","is_correct":true},{"text":"trabajo","is_correct":false},{"text":"trabajas","is_correct":false},{"text":"trabajan","is_correct":false}],"explanation":"Correct! \"Él trabaja\" means \"He works\". For -AR verbs with \"él\", use the -a ending."},{"type":"exercise","id":"exercise5","question":"Which is correct: \"Ellos viven\" or \"Ellos vive\"?","options":[{"text":"Ellos viven","is_correct":true},{"text":"Ellos vive","is_correct":false},{"text":"Both are correct","is_correct":false},{"text":"Ellos vivir","is_correct":false}],"explanation":"Correct! \"Ellos viven\" means \"They live\". For plural subjects (ellos/ellas), use -en ending with -IR verbs."},{"type":"text","id":"summary","title":"Summary: Present Tense Conjugation","content":"Great work! You''ve learned the three main verb types in Spanish:\n\n1. -AR verbs (most common): hablo, hablas, habla, hablamos, habláis, hablan\n2. -ER verbs: como, comes, come, comemos, coméis, comen\n3. -IR verbs: vivo, vives, vive, vivimos, vivís, viven\n\nKey points to remember:\n• All verbs use -o for \"yo\"\n• -AR and -ER/-IR differ in tú, él, ellos forms\n• -ER and -IR differ only in nosotros form (-emos vs -imos)","examples":["Practice conjugating verbs daily","Start with common verbs you use often","Pay attention to the infinitive ending"]}]}'::jsonb,
  ARRAY['hablar', 'comer', 'vivir', 'caminar', 'trabajar', 'beber', 'escribir', 'estudiar', 'aprender', 'entender']::TEXT[],
  ARRAY['present_tense', 'ar_verbs', 'er_verbs', 'ir_verbs', 'verb_conjugation']::TEXT[]
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  estimated_minutes = EXCLUDED.estimated_minutes,
  content_json = EXCLUDED.content_json,
  unlocks_word_ids = EXCLUDED.unlocks_word_ids,
  unlocks_grammar_concepts = EXCLUDED.unlocks_grammar_concepts,
  updated_at = NOW();

-- Articles: El, La, Los, Las
INSERT INTO lessons (id, title, description, language, category, order_index, estimated_minutes, content_json, unlocks_word_ids, unlocks_grammar_concepts)
VALUES (
  'spanish_articles',
  'Articles: El, La, Los, Las',
  'Learn about Spanish definite articles and gender agreement',
  'spanish',
  'articles',
  2,
  25,
  '{"sections":[{"type":"text","id":"intro","title":"What are Articles?","content":"Articles are small words that come before nouns. In English, we have \"the\" and \"a/an\". Spanish has more articles because they must match the noun''s gender (masculine/feminine) and number (singular/plural).\n\nThis lesson covers:\n• Definite articles (the)\n• Indefinite articles (a/an)\n• Gender agreement rules","examples":["el libro (the book) - masculine singular","la mesa (the table) - feminine singular","los libros (the books) - masculine plural","las mesas (the tables) - feminine plural"]},{"type":"text","id":"definite_intro","title":"Definite Articles: \"The\"","content":"Spanish has four definite articles (meaning \"the\"):\n\n• el (masculine singular) - the\n• la (feminine singular) - the\n• los (masculine plural) - the\n• las (feminine plural) - the\n\nThe article must match the noun in both gender and number!","examples":["el gato (the cat) - masculine singular","la gata (the female cat) - feminine singular","los gatos (the cats) - masculine plural","las gatas (the female cats) - feminine plural"]},{"type":"example","id":"example1","spanish_example":"El gato es negro","english_translation":"The cat is black","explanation":"\"Gato\" (cat) is masculine singular, so we use \"el\". Notice \"negro\" (black) also agrees with the masculine noun."},{"type":"example","id":"example1b","spanish_example":"La gata es negra","english_translation":"The female cat is black","explanation":"\"Gata\" (female cat) is feminine singular, so we use \"la\". Also notice \"negra\" (black) changes to feminine form!"},{"type":"example","id":"example2","spanish_example":"La casa es grande","english_translation":"The house is big","explanation":"\"Casa\" (house) is feminine singular, so we use \"la\". Most words ending in -a are feminine."},{"type":"example","id":"example2b","spanish_example":"Los libros son interesantes","english_translation":"The books are interesting","explanation":"\"Libros\" (books) is masculine plural, so we use \"los\". Notice \"son\" (are) is used for plural."},{"type":"exercise","id":"exercise1","question":"Which article is correct for \"casa\" (house)?","options":[{"text":"la","is_correct":true},{"text":"el","is_correct":false},{"text":"los","is_correct":false},{"text":"las","is_correct":false}],"explanation":"Correct! \"Casa\" is feminine singular, so we use \"la casa\". Most words ending in -a are feminine."},{"type":"exercise","id":"exercise1b","question":"Complete: \"_____ gato es pequeño.\" (The cat is small)","options":[{"text":"El","is_correct":true},{"text":"La","is_correct":false},{"text":"Los","is_correct":false},{"text":"Las","is_correct":false}],"explanation":"Correct! \"Gato\" (cat) is masculine singular, so use \"el\"."},{"type":"exercise","id":"exercise2","question":"How do you say \"the books\" in Spanish?","options":[{"text":"los libros","is_correct":true},{"text":"el libro","is_correct":false},{"text":"la libro","is_correct":false},{"text":"las libros","is_correct":false}],"explanation":"Correct! \"Libro\" is masculine and becomes \"libros\" (plural), so we use \"los libros\"."},{"type":"exercise","id":"exercise2b","question":"Complete: \"_____ mesas son grandes.\" (The tables are big)","options":[{"text":"Las","is_correct":true},{"text":"La","is_correct":false},{"text":"Los","is_correct":false},{"text":"El","is_correct":false}],"explanation":"Correct! \"Mesa\" is feminine and becomes \"mesas\" (plural), so use \"las\"."},{"type":"text","id":"indefinite_intro","title":"Indefinite Articles: \"A/An\"","content":"Spanish also has indefinite articles (meaning \"a\" or \"an\"):\n\n• un (masculine singular) - a/an\n• una (feminine singular) - a/an\n• unos (masculine plural) - some\n• unas (feminine plural) - some\n\nThese also must match the noun''s gender and number!","examples":["un libro (a book) - masculine singular","una mesa (a table) - feminine singular","unos libros (some books) - masculine plural","unas mesas (some tables) - feminine plural"]},{"type":"example","id":"example3","spanish_example":"Tengo un perro","english_translation":"I have a dog","explanation":"\"Perro\" (dog) is masculine singular, so we use \"un\". \"Tengo\" means \"I have\"."},{"type":"example","id":"example3b","spanish_example":"Ella tiene una gata","english_translation":"She has a female cat","explanation":"\"Gata\" (female cat) is feminine singular, so we use \"una\". \"Ella tiene\" means \"she has\"."},{"type":"exercise","id":"exercise3","question":"Complete: \"Necesito _____ libro.\" (I need a book)","options":[{"text":"un","is_correct":true},{"text":"una","is_correct":false},{"text":"el","is_correct":false},{"text":"la","is_correct":false}],"explanation":"Correct! \"Libro\" is masculine singular, so use \"un libro\" (a book)."},{"type":"exercise","id":"exercise3b","question":"How do you say \"some apples\" in Spanish? (manzana = apple)","options":[{"text":"unas manzanas","is_correct":true},{"text":"una manzana","is_correct":false},{"text":"unos manzanas","is_correct":false},{"text":"las manzanas","is_correct":false}],"explanation":"Correct! \"Manzana\" is feminine and becomes \"manzanas\" (plural), so use \"unas manzanas\" (some apples)."},{"type":"text","id":"gender_rules","title":"Gender Rules: How to Know?","content":"How do you know if a noun is masculine or feminine?\n\nGeneral rules:\n• Words ending in -o are usually masculine: el libro, el gato\n• Words ending in -a are usually feminine: la casa, la mesa\n• Words ending in -ión are usually feminine: la nación, la acción\n• Words ending in -dad/-tad are usually feminine: la ciudad, la libertad\n\nBut there are exceptions! You''ll learn them with practice.","examples":["el problema (the problem) - ends in -a but is masculine!","la mano (the hand) - ends in -o but is feminine!","el día (the day) - ends in -a but is masculine!"]},{"type":"exercise","id":"exercise4","question":"Which article would you use for \"problema\" (problem)?","options":[{"text":"el","is_correct":true},{"text":"la","is_correct":false},{"text":"los","is_correct":false},{"text":"las","is_correct":false}],"explanation":"Correct! Even though \"problema\" ends in -a, it''s masculine! This is an exception. Use \"el problema\"."},{"type":"exercise","id":"exercise4b","question":"Complete: \"_____ mano es pequeña.\" (The hand is small)","options":[{"text":"La","is_correct":true},{"text":"El","is_correct":false},{"text":"Los","is_correct":false},{"text":"Las","is_correct":false}],"explanation":"Correct! \"Mano\" (hand) ends in -o but is feminine! This is an exception. Use \"la mano\"."},{"type":"text","id":"summary","title":"Summary: Articles in Spanish","content":"Excellent work! You''ve learned:\n\nDefinite Articles (the):\n• el / la (singular)\n• los / las (plural)\n\nIndefinite Articles (a/an, some):\n• un / una (singular)\n• unos / unas (plural)\n\nKey points:\n• Articles must match gender (masculine/feminine)\n• Articles must match number (singular/plural)\n• Most -o words are masculine, most -a words are feminine\n• But there are exceptions you''ll learn with practice!","examples":["Practice with common nouns daily","Pay attention to article-noun agreement","Learn exceptions as you encounter them"]}]}'::jsonb,
  ARRAY['el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas', 'casa', 'libro', 'mesa', 'gato', 'perro', 'manzana', 'problema', 'mano']::TEXT[],
  ARRAY['articles', 'definite_articles', 'indefinite_articles', 'gender_agreement', 'number_agreement']::TEXT[]
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  estimated_minutes = EXCLUDED.estimated_minutes,
  content_json = EXCLUDED.content_json,
  unlocks_word_ids = EXCLUDED.unlocks_word_ids,
  unlocks_grammar_concepts = EXCLUDED.unlocks_grammar_concepts,
  updated_at = NOW();

-- Subject Pronouns
INSERT INTO lessons (id, title, description, language, category, order_index, estimated_minutes, content_json, unlocks_word_ids, unlocks_grammar_concepts)
VALUES (
  'spanish_subject_pronouns',
  'Subject Pronouns',
  'Learn Spanish subject pronouns: yo, tú, él, ella, etc.',
  'spanish',
  'pronouns',
  3,
  7,
  '{"sections":[{"type":"text","id":"intro","title":"Subject Pronouns","content":"Subject pronouns in Spanish are: yo (I), tú (you informal), él (he), ella (she), nosotros/nosotras (we), vosotros/vosotras (you plural), ellos/ellas (they).","examples":["Yo soy estudiante (I am a student)","Tú eres profesor (You are a teacher)","Él es médico (He is a doctor)"]},{"type":"example","id":"example1","spanish_example":"Yo hablo español","english_translation":"I speak Spanish","explanation":"\"Yo\" is the first person singular pronoun"},{"type":"exercise","id":"exercise1","question":"Which pronoun means \"we\" (masculine)?","options":[{"text":"yo","is_correct":false},{"text":"tú","is_correct":false},{"text":"nosotros","is_correct":true},{"text":"ellos","is_correct":false}],"explanation":"Correct! \"Nosotros\" means \"we\" (masculine or mixed group)."}]}'::jsonb,
  ARRAY['yo', 'tú', 'él', 'ella', 'nosotros', 'nosotras', 'ellos', 'ellas']::TEXT[],
  ARRAY['subject_pronouns']::TEXT[]
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  estimated_minutes = EXCLUDED.estimated_minutes,
  content_json = EXCLUDED.content_json,
  unlocks_word_ids = EXCLUDED.unlocks_word_ids,
  unlocks_grammar_concepts = EXCLUDED.unlocks_grammar_concepts,
  updated_at = NOW();

-- Basic Sentence Structure
INSERT INTO lessons (id, title, description, language, category, order_index, estimated_minutes, content_json, unlocks_word_ids, unlocks_grammar_concepts)
VALUES (
  'spanish_basic_sentence_structure',
  'Basic Sentence Structure',
  'Learn how to build basic Spanish sentences',
  'spanish',
  'syntax',
  4,
  30,
  '{"sections":[{"type":"text","id":"intro","title":"Building Sentences in Spanish","content":"Spanish sentences follow a specific word order, similar to English but with some important differences.\n\nBasic pattern:\nSubject + Verb + Object\n\nBut remember:\n• Articles and adjectives must agree with nouns\n• Adjectives usually come AFTER nouns\n• Questions use inverted word order or question words","examples":["El gato come pescado (The cat eats fish)","La niña juega en el parque (The girl plays in the park)","El libro es interesante (The book is interesting)"]},{"type":"text","id":"simple_sentences","title":"Simple Sentences: Subject + Verb","content":"The simplest sentences have just a subject and a verb. The subject can be:\n• A noun with article: \"El perro corre\"\n• A pronoun: \"Yo hablo\"\n• Or omitted: \"Hablo\" (I speak)","examples":["El perro corre (The dog runs)","Yo estudio (I study)","Ella canta (She sings)"]},{"type":"example","id":"example1","spanish_example":"El perro corre","english_translation":"The dog runs","explanation":"Simple sentence: Subject (el perro) + Verb (corre). Notice the article \"el\" agrees with the masculine noun \"perro\"."},{"type":"example","id":"example1b","spanish_example":"Las niñas juegan","english_translation":"The girls play","explanation":"Subject (las niñas) + Verb (juegan). Notice \"las\" (plural feminine) and \"juegan\" (plural verb form)."},{"type":"exercise","id":"exercise1","question":"Complete: \"_____ gato duerme.\" (The cat sleeps)","options":[{"text":"El","is_correct":true},{"text":"La","is_correct":false},{"text":"Los","is_correct":false},{"text":"Las","is_correct":false}],"explanation":"Correct! \"Gato\" (cat) is masculine singular, so use \"el\". The sentence is: \"El gato duerme\" (The cat sleeps)."},{"type":"text","id":"object_intro","title":"Adding Objects: Subject + Verb + Object","content":"When you add an object (what receives the action), the order is:\n\nSubject + Verb + Direct Object\n\nExamples:\n• El niño come una manzana (The boy eats an apple)\n• La mujer lee un libro (The woman reads a book)\n• Yo compro pan (I buy bread)","examples":["El niño come una manzana (The boy eats an apple)","La mujer lee un libro (The woman reads a book)","Nosotros compramos pan (We buy bread)"]},{"type":"example","id":"example2","spanish_example":"La niña come una manzana","english_translation":"The girl eats an apple","explanation":"Subject (la niña) + Verb (come) + Object (una manzana). Notice \"una\" (feminine) agrees with \"manzana\"."},{"type":"example","id":"example2b","spanish_example":"El estudiante lee los libros","english_translation":"The student reads the books","explanation":"Subject (el estudiante) + Verb (lee) + Object (los libros). Notice \"los\" (masculine plural) agrees with \"libros\"."},{"type":"exercise","id":"exercise2","question":"What is the correct order for \"The boy eats an apple\"?","options":[{"text":"El niño come una manzana","is_correct":true},{"text":"Come el niño una manzana","is_correct":false},{"text":"Una manzana come el niño","is_correct":false},{"text":"El niño una manzana come","is_correct":false}],"explanation":"Correct! Spanish follows Subject + Verb + Object order: \"El niño come una manzana\"."},{"type":"exercise","id":"exercise2b","question":"Complete: \"La mujer _____ un libro.\" (The woman reads a book)","options":[{"text":"lee","is_correct":true},{"text":"leer","is_correct":false},{"text":"leemos","is_correct":false},{"text":"leen","is_correct":false}],"explanation":"Correct! \"La mujer\" (the woman) is third person singular, so use \"lee\" (reads)."},{"type":"text","id":"adjectives_intro","title":"Adding Adjectives","content":"In Spanish, adjectives usually come AFTER the noun (unlike English!):\n\n• El libro interesante (The interesting book)\n• La casa grande (The big house)\n• Los gatos negros (The black cats)\n\nAdjectives must agree with the noun in:\n• Gender (masculine/feminine)\n• Number (singular/plural)","examples":["El libro interesante (The interesting book)","La casa grande (The big house)","Los gatos negros (The black cats)","Las casas grandes (The big houses)"]},{"type":"example","id":"example3","spanish_example":"El gato negro duerme","english_translation":"The black cat sleeps","explanation":"Notice \"negro\" (black) comes AFTER \"gato\" and agrees with it (masculine singular). In English, adjectives come before nouns!"},{"type":"example","id":"example3b","spanish_example":"Las casas grandes son bonitas","english_translation":"The big houses are pretty","explanation":"Both \"grandes\" (big) and \"bonitas\" (pretty) come after the noun and agree: feminine plural. \"Son\" means \"are\"."},{"type":"exercise","id":"exercise3","question":"Complete: \"El libro _____ es interesante.\" (The red book is interesting)","options":[{"text":"rojo","is_correct":true},{"text":"roja","is_correct":false},{"text":"rojos","is_correct":false},{"text":"rojas","is_correct":false}],"explanation":"Correct! \"Libro\" is masculine singular, so \"rojo\" (red) must also be masculine singular. The adjective comes after the noun."},{"type":"exercise","id":"exercise3b","question":"Which sentence is correct?","options":[{"text":"La casa grande","is_correct":true},{"text":"La grande casa","is_correct":false},{"text":"Grande la casa","is_correct":false},{"text":"La casa grande es","is_correct":false}],"explanation":"Correct! In Spanish, adjectives usually come AFTER the noun: \"la casa grande\" (the big house)."},{"type":"text","id":"questions_intro","title":"Forming Questions","content":"Spanish questions can be formed in two ways:\n\n1. Invert word order:\n• \"¿Hablas español?\" (Do you speak Spanish?)\n• \"¿Come el gato?\" (Does the cat eat?)\n\n2. Use question words:\n• ¿Qué? (What?)\n• ¿Quién? (Who?)\n• ¿Dónde? (Where?)\n• ¿Cuándo? (When?)\n• ¿Por qué? (Why?)\n• ¿Cómo? (How?)","examples":["¿Hablas español? (Do you speak Spanish?)","¿Qué comes? (What do you eat?)","¿Dónde vives? (Where do you live?)"]},{"type":"example","id":"example4","spanish_example":"¿Hablas español?","english_translation":"Do you speak Spanish?","explanation":"Question formed by inverting word order. In statements: \"Tú hablas español\". In questions: \"¿Hablas español?\" (pronoun often omitted)."},{"type":"example","id":"example4b","spanish_example":"¿Qué comes?","english_translation":"What do you eat?","explanation":"Question using \"¿Qué?\" (What?). The question word comes first, then the verb. \"Comes\" means \"you eat\"."},{"type":"exercise","id":"exercise4","question":"How would you ask \"Where do you live?\" in Spanish?","options":[{"text":"¿Dónde vives?","is_correct":true},{"text":"¿Dónde vives tú?","is_correct":false},{"text":"¿Vives dónde?","is_correct":false},{"text":"¿Dónde tú vives?","is_correct":false}],"explanation":"Correct! \"¿Dónde vives?\" means \"Where do you live?\". The question word comes first, then the verb. The pronoun is usually omitted."},{"type":"exercise","id":"exercise4b","question":"Complete: \"¿_____ estudias?\" (What do you study?)","options":[{"text":"Qué","is_correct":true},{"text":"Quién","is_correct":false},{"text":"Dónde","is_correct":false},{"text":"Cuándo","is_correct":false}],"explanation":"Correct! \"¿Qué estudias?\" means \"What do you study?\". \"Qué\" means \"what\"."},{"type":"text","id":"negation_intro","title":"Making Negative Sentences","content":"To make a sentence negative in Spanish, put \"no\" BEFORE the verb:\n\n• No hablo español (I don''t speak Spanish)\n• No como carne (I don''t eat meat)\n• No tengo hambre (I am not hungry)\n\nYou can also use other negative words:\n• nunca (never)\n• nada (nothing)\n• nadie (nobody)","examples":["No hablo español (I don''t speak Spanish)","Nunca como carne (I never eat meat)","No tengo nada (I don''t have anything)"]},{"type":"example","id":"example5","spanish_example":"No hablo inglés","english_translation":"I don''t speak English","explanation":"Simply put \"no\" before the verb to make it negative. \"No hablo\" means \"I don''t speak\"."},{"type":"exercise","id":"exercise5","question":"How would you say \"I don''t eat meat\" in Spanish?","options":[{"text":"No como carne","is_correct":true},{"text":"Como no carne","is_correct":false},{"text":"No carne como","is_correct":false},{"text":"Como carne no","is_correct":false}],"explanation":"Correct! Put \"no\" before the verb: \"No como carne\" (I don''t eat meat)."},{"type":"text","id":"summary","title":"Summary: Sentence Structure","content":"Excellent work! You''ve learned:\n\nBasic word order:\n• Subject + Verb + Object\n• El niño come una manzana\n\nAdjectives:\n• Usually come AFTER nouns\n• Must agree in gender and number\n• La casa grande (the big house)\n\nQuestions:\n• Invert word order or use question words\n• ¿Hablas español? (Do you speak Spanish?)\n• ¿Qué comes? (What do you eat?)\n\nNegation:\n• Put \"no\" before the verb\n• No hablo español (I don''t speak Spanish)","examples":["Practice building sentences daily","Pay attention to word order","Remember adjective placement and agreement"]}]}'::jsonb,
  ARRAY['perro', 'gato', 'niño', 'niña', 'libro', 'manzana', 'casa', 'estudiante', 'qué', 'dónde', 'cuándo', 'cómo']::TEXT[],
  ARRAY['basic_sentence_structure', 'subject_verb_object', 'adjective_placement', 'question_formation', 'negation', 'word_order']::TEXT[]
) ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  estimated_minutes = EXCLUDED.estimated_minutes,
  content_json = EXCLUDED.content_json,
  unlocks_word_ids = EXCLUDED.unlocks_word_ids,
  unlocks_grammar_concepts = EXCLUDED.unlocks_grammar_concepts,
  updated_at = NOW();

